#param lib("array")
#param lib("math")

/* graphics.c - VML QBASIC-style Graphics Library
 * SCREEN mode, palette, pixel/line/rect/circle/arc/sector, bitmap text
 * All 16 languages call these entry points.
 */

// === VGA Memory Map ===
// VGA_GFX_FB   = framebuffer base (GetConfig #1)
// VGA_MODE     = 0x6FF0  (0=text, 13=320x200x256, etc.)
// CURSOR_ROW   = 0x6FF4
// CURSOR_COL   = 0x6FF8
// FG_COLOR     = 0x6FFC
// BG_COLOR     = 0x6FFD
// QB_PALETTE   = 0x6F00  (16 entries x 3 bytes RGB)
// QB_PALETTE256= 0x7800  (256 entries x 3 bytes RGB)

// === Cached framebuffer params (refreshed once after SCREEN mode change) ===
static int _gfx_fb = 0;
static int _gfx_w = 0;
static int _gfx_h = 0;
static int _vml_result_int = 0;
static int _gfx_y = 0;     // temp for asm circle
static int _gfx_d = 0;     // temp for asm circle

static void _gfx_refresh_cache(void) {
    asm("LOAD R0 #1");
    asm("SYSCALL 60");
    asm("STORE R0, _gfx_fb");
    // Read VGA mode from 0x6FF0 to get correct dimensions.
    // SYSCALL 60 codes 8/9 return device config (80x25), not VGA mode size.
    int mode = *(volatile char*)0x6FF0;
    if (mode == 0)      { _gfx_w = 80;  _gfx_h = 25;  }
    else if (mode == 1)  { _gfx_w = 320; _gfx_h = 200; }
    else if (mode == 2)  { _gfx_w = 640; _gfx_h = 200; }
    else if (mode == 3)  { _gfx_w = 720; _gfx_h = 400; }
    else if (mode == 7)  { _gfx_w = 320; _gfx_h = 200; }
    else if (mode == 8)  { _gfx_w = 640; _gfx_h = 200; }
    else if (mode == 9)  { _gfx_w = 640; _gfx_h = 350; }
    else if (mode == 10) { _gfx_w = 640; _gfx_h = 350; }
    else if (mode == 11) { _gfx_w = 640; _gfx_h = 480; }
    else if (mode == 12) { _gfx_w = 640; _gfx_h = 480; }
    else if (mode == 13) { _gfx_w = 320; _gfx_h = 200; }
    else if (mode == 14) { _gfx_w = 640; _gfx_h = 480; }
    else if (mode == 15) { _gfx_w = 800; _gfx_h = 600; }
    else                 { _gfx_w = 320; _gfx_h = 200; }
}

// === Helper: call SYSCALL 60 to get config values (for one-shot queries) ===
// Parameter 'code' is already in R0 via calling convention
static int get_config(int code) {
    asm("SYSCALL 60");
    asm("STORE R0, _vml_result_int");
    return _vml_result_int;
}

static int* gfx_fb()     { return (int*)_gfx_fb; }
static int gfx_w()       { return _gfx_w; }
static int gfx_h()       { return _gfx_h; }

// === Screen Mode ===
// mode: 0=text, 1=320x200x4, 2=640x480x2, 7=320x200x16,
//       8=640x200x16, 9=640x350x16, 10=640x350x4,
//       11=640x480x2, 12=640x480x16, 13=320x200x256,
//       14=640x480x256, 15=800x600x256
int gfx_screen(int mode) {
    if (mode < 0) {
        // query mode: return current mode
        // LOADB works correctly; compiler can handle volatile char* reads
        return *(volatile char*)0x6FF0;
    }
    // Use asm for STOREB — compiler drops *(volatile char*)... = val
    // regardless of constant or variable address. Workaround: emulate
    // gfx_palette's pattern by loading address into R4 and using [R4] store.
    asm("LOAD R4 #28656");       // R4 = VGA_MODE address (0x6FF0)
    asm("LOAD R0 [R12+12]");     // R0 = mode (saved in frame by prologue)
    asm("STOREB R0 [R4]");       // *(volatile char*)0x6FF0 = mode
    asm("LOAD R0 #1");
    asm("STOREB R0 [R4+3]");     // *(volatile char*)0x6FF3 = 1 (mbpp)
    _gfx_refresh_cache();
    return mode;
}

// === Resolution & Color Depth ===
int gfx_width()  { if (_gfx_w <= 0) _gfx_refresh_cache(); return _gfx_w; }
int gfx_height() { if (_gfx_w <= 0) _gfx_refresh_cache(); return _gfx_h; }

int gfx_depth() {
    int mode = *(volatile char*)0x6FF0;
    // Return bits per pixel based on SCREEN mode
    if (mode == 0)  return 4;   // text mode, 16 colors
    if (mode == 1)  return 2;   // CGA 4-color
    if (mode == 2)  return 1;   // 2-color
    if (mode == 7)  return 4;   // EGA 16-color
    if (mode == 8)  return 4;
    if (mode == 9)  return 4;
    if (mode == 10) return 2;
    if (mode == 11) return 1;
    if (mode == 12) return 4;
    if (mode == 13) return 8;   // VGA 256-color
    if (mode == 14) return 8;
    if (mode == 15) return 8;
    return 1; // default
}

// === Palette ===
// Palette at 0x6F00 (16-col) or 0x7800 (256-col)
// Each entry: 3 bytes (R, G, B), values 0-63 (VGA DAC)

void gfx_palette(int index, int r, int g, int b) {
    // Use asm because compiler drops *(volatile char*)addr = val STOREB
    asm("PUSH R4");
    asm("PUSH R5");
    asm("LOAD R4 [R12+12]");     // R4 = index (R0)
    asm("MUL R4 3");             // R4 = index * 3
    asm("LOAD R5 #30720");       // R5 = 0x7800 (256-col palette base)
    asm("ADD R4 R5");            // R4 = 0x7800 + index*3
    asm("LOAD R5 [R12+16]");     // R5 = r (R1)
    asm("STOREB R5 [R4]");       // palette[index].r = r
    asm("LOAD R5 [R12+20]");     // R5 = g (R2)
    asm("STOREB R5 [R4+1]");     // palette[index].g = g
    asm("LOAD R5 [R12+24]");     // R5 = b (R3)
    asm("STOREB R5 [R4+2]");     // palette[index].b = b
    asm("POP R5");
    asm("POP R4");
}

int gfx_palette_get(int index) {
    // Use asm because compiler may drop LOADB from computed addresses
    asm("LOAD R4 [R12+12]");     // R4 = index (R0)
    asm("MUL R4 3");             // R4 = index * 3
    asm("LOAD R5 #30720");       // R5 = 0x7800
    asm("ADD R4 R5");            // R4 = 0x7800 + index*3
    asm("LOADB R5 [R4]");        // R5 = r
    asm("STORE R5, _vml_result_int");
    asm("LOADB R5 [R4+1]");      // R5 = g
    asm("STORE R5, _vml_result_int");
    asm("LOADB R5 [R4+2]");      // R5 = b
    asm("STORE R5, _vml_result_int");
    return _vml_result_int;      // returns b (last stored), sufficient for most uses
}

// === Pixel Operations ===

static void _putpixel(int x, int y, int color) {
    // Lazy refresh: if cache is stale, refresh it
    if (_gfx_w <= 0) _gfx_refresh_cache();
    if (x < 0 || x >= _gfx_w || y < 0 || y >= _gfx_h) return;
    // Direct framebuffer write via asm — compiler drops *(char*)var = val STOREB
    // Save R4 to global instead of PUSH (PUSH modifies SP which may confuse the
    // compiler when _putpixel is called from functions with 5+ params).
    asm("STORE R4, _vml_result_int");  // save caller's R4
    asm("LOAD R4 [R12+16]");     // R4 = y param
    asm("LOAD R0 [_gfx_w]");     // R0 = _gfx_w
    asm("MUL R4 R0");            // R4 = y * _gfx_w
    asm("LOAD R0 [R12+12]");     // R0 = x param
    asm("ADD R4 R0");            // R4 = y * _gfx_w + x
    asm("LOAD R0 [_gfx_fb]");   // R0 = _gfx_fb
    asm("ADD R4 R0");            // R4 = _gfx_fb + y * _gfx_w + x
    asm("LOAD R0 [R12+20]");     // R0 = color param
    asm("STOREB R0 [R4]");       // write pixel
    asm("LOAD R4, _vml_result_int");   // restore caller's R4
}

static int _getpixel(int x, int y) {
    if (_gfx_w <= 0) _gfx_refresh_cache();
    if (x < 0 || x >= _gfx_w || y < 0 || y >= _gfx_h) return -1;
    // Use asm for LOADB — compiler may also drop *(char*)var reads
    asm("STORE R4, _vml_result_int");  // save caller's R4
    asm("LOAD R4 [R12+16]");     // R4 = y param
    asm("LOAD R0 [_gfx_w]");     // R0 = _gfx_w
    asm("MUL R4 R0");            // R4 = y * _gfx_w
    asm("LOAD R0 [R12+12]");     // R0 = x param
    asm("ADD R4 R0");            // R4 = y * _gfx_w + x
    asm("LOAD R0 [_gfx_fb]");   // R0 = _gfx_fb
    asm("ADD R4 R0");            // R4 = _gfx_fb + y * _gfx_w + x
    asm("LOADB R0 [R4]");        // read pixel into R0 (return value)
    asm("LOAD R4, _vml_result_int");   // restore caller's R4
}

void gfx_pset(int x, int y, int color) {
    _putpixel(x, y, color);
}

int gfx_point(int x, int y) {
    return _getpixel(x, y);
}

// === Clear Screen ===
void gfx_cls() {
    gfx_cls_color(0);
}

void gfx_cls_color(int color) {
    if (_gfx_w <= 0) _gfx_refresh_cache();
    int total = _gfx_w * _gfx_h;
    int i;
    for (i = 0; i < total; i++) {
        _putpixel_fast(i, color);
    }
}

// Fast pixel write by linear offset (no bounds check, no y*x+w multiply)
static void _putpixel_fast(int offset, int color) {
    // Save R4,R5 used by asm blocks to avoid corrupting caller's loop variables
    asm("PUSH R4");
    asm("PUSH R5");
    asm("LOAD R4 [_gfx_fb]");    // R4 = framebuffer base
    asm("LOAD R5 [R12+12]");     // R5 = offset (1st param = R0)
    asm("ADD R4 R5");            // R4 = fb + offset
    asm("LOAD R5 [R12+16]");     // R5 = color (2nd param = R1)
    asm("STOREB R5 [R4]");       // write pixel
    asm("POP R5");
    asm("POP R4");
}

// === Bresenham Line ===
void gfx_line(int x1, int y1, int x2, int y2, int color) {
    int dx, dy, sx, sy, err, e2;
    // Force VML C compiler to save R4 (5th param color) to the stack frame.
    // The compiler generates prologue STORE for R0-R3 but not R4.
    asm("STORE R4, _vml_result_int");
    color = _vml_result_int;
    dx = x2 - x1;
    if (dx < 0) dx = -dx;
    dy = y2 - y1;
    if (dy < 0) dy = -dy;
    sx = (x1 < x2) ? 1 : -1;
    sy = (y1 < y2) ? 1 : -1;
    err = dx - dy;

    while (1) {
        _putpixel(x1, y1, color);
        if (x1 == x2 && y1 == y2) break;
        e2 = 2 * err;
        if (e2 > -dy) {
            err = err - dy;
            x1 = x1 + sx;
        }
        if (e2 < dx) {
            err = err + dx;
            y1 = y1 + sy;
        }
    }
}

// === Rectangle ===
void gfx_rect(int x1, int y1, int x2, int y2, int color) {
    gfx_line(x1, y1, x2, y1, color);
    gfx_line(x2, y1, x2, y2, color);
    gfx_line(x2, y2, x1, y2, color);
    gfx_line(x1, y2, x1, y1, color);
}

void gfx_rect_fill(int x1, int y1, int x2, int y2, int color) {
    int x, y, tmp;
    if (x1 > x2) { tmp = x1; x1 = x2; x2 = tmp; }
    if (y1 > y2) { tmp = y1; y1 = y2; y2 = tmp; }
    for (y = y1; y <= y2; y++) {
        for (x = x1; x <= x2; x++) {
            _putpixel(x, y, color);
        }
    }
}

// === Bresenham Circle ===
void gfx_circle(int cx, int cy, int r, int color) {
    volatile int x = 0;
    volatile int y = r;
    volatile int d = 3 - 2 * r;
    while (y >= x) {
        int px, py;
        px = cx + x; py = cy + y; _putpixel(px, py, color);
        px = cx - x; py = cy + y; _putpixel(px, py, color);
        px = cx + x; py = cy - y; _putpixel(px, py, color);
        px = cx - x; py = cy - y; _putpixel(px, py, color);
        px = cx + y; py = cy + x; _putpixel(px, py, color);
        px = cx - y; py = cy + x; _putpixel(px, py, color);
        px = cx + y; py = cy - x; _putpixel(px, py, color);
        px = cx - y; py = cy - x; _putpixel(px, py, color);
        x = x + 1;
        if (d > 0) {
            y = y - 1;
            d = d + 4 * (x - y) + 10;
        } else {
            d = d + 4 * x + 6;
        }
    }
}

void gfx_circle_fill(int cx, int cy, int r, int color) {
    int x = 0;
    int y = r;
    int d = 3 - 2 * r;
    while (y >= x) {
        int i;
        i = cx - x;
        while (i <= cx + x) { _putpixel(i, cy + y, color); _putpixel(i, cy - y, color); i = i + 1; }
        i = cx - y;
        while (i <= cx + y) { _putpixel(i, cy + x, color); _putpixel(i, cy - x, color); i = i + 1; }
        x = x + 1;
        if (d > 0) { y = y - 1; d = d + 4 * (x - y) + 10; }
        else { d = d + 4 * x + 6; }
    }
}

// === Arc (approximate, using angle in degrees 0-360) ===
void gfx_arc(int cx, int cy, int r, int start_angle, int end_angle, int color) {
    int a;
    // Fixed-point: use 64 as scale factor for sin/cos approximation
    // Draw arc using iterative angle calculation
    if (start_angle > end_angle) { int tmp = start_angle; start_angle = end_angle; end_angle = tmp; }
    int prev_x = -1, prev_y = -1;
    for (a = start_angle; a <= end_angle; a++) {
        // Simple fixed-point sin/cos using small-angle approximation
        // angle in degrees, radius r
        // x = r * cos(a), y = r * sin(a)
        // Use precomputed table approach or approximation
        int rad = (a * 1144) / 65536;  // rough deg->rad (not accurate but functional)
        // Use integer approximation: cos(a) ~ 64 at 0°, sin(a) ~ a*64/90 for small angles
        // For full implementation, use the math library
        // Here we use a simple octant-based approximation
        int angle = a % 360;
        int sx, sy;
        // Use CALL to shared math functions if available; here use coarse approximation
        if (angle <= 90) {
            sx = (90 - angle) * r / 90;
            sy = angle * r / 90;
        } else if (angle <= 180) {
            sx = -(angle - 90) * r / 90;
            sy = (180 - angle) * r / 90;
        } else if (angle <= 270) {
            sx = -(270 - angle) * r / 90;
            sy = -(angle - 180) * r / 90;
        } else {
            sx = (angle - 270) * r / 90;
            sy = -(360 - angle) * r / 90;
        }
        int px = cx + sx;
        int py = cy + sy;
        _putpixel(px, py, color);
    }
}

// === Ellipse (Bresenham) ===
void gfx_ellipse(int cx, int cy, int rx, int ry, int color) {
    int x = 0;
    int y = ry;
    int rx2 = rx * rx;
    int ry2 = ry * ry;
    int tworx2 = 2 * rx2;
    int twory2 = 2 * ry2;
    int px = 0;
    int py = tworx2 * y;
    int p = ry2 - rx2 * ry + rx2 / 4;

    // Region 1
    while (px < py) {
        _putpixel(cx + x, cy + y, color);
        _putpixel(cx - x, cy + y, color);
        _putpixel(cx + x, cy - y, color);
        _putpixel(cx - x, cy - y, color);
        x = x + 1;
        px = px + twory2;
        if (p < 0) { p = p + ry2 + px; }
        else { y = y - 1; py = py - tworx2; p = p + ry2 + px - py; }
    }

    // Region 2 — p computed stepwise to avoid compiler MUL bugs
    {
        int t1, t2, t3;
        t1 = x * x + x;
        t2 = y - 1;
        t3 = t2 * t2;
        p = ry2 * t1;
        p = p + rx2 * t3;
        p = p - rx2 * ry2;
    }
    while (y >= 0) {
        _putpixel(cx + x, cy + y, color);
        _putpixel(cx - x, cy + y, color);
        _putpixel(cx + x, cy - y, color);
        _putpixel(cx - x, cy - y, color);
        y = y - 1;
        py = py - tworx2;
        if (p > 0) { p = p + rx2 - py; }
        else { x = x + 1; px = px + twory2; p = p + rx2 - py + px; }
    }
}

// === Filled Ellipse ===
void gfx_ellipse_fill(int cx, int cy, int rx, int ry, int color) {
    int x = 0;
    int y = ry;
    int rx2 = rx * rx;
    int ry2 = ry * ry;
    int tworx2 = 2 * rx2;
    int twory2 = 2 * ry2;
    int px = 0;
    int py = tworx2 * y;
    int p = ry2 - rx2 * ry + rx2 / 4;

    // Region 1
    while (px < py) {
        int _x1, _y1, _x2, _y2;
        _x1 = cx - x; _y1 = cy + y; _x2 = cx + x; _y2 = cy + y;
        gfx_line(_x1, _y1, _x2, _y2, color);
        _x1 = cx - x; _y1 = cy - y; _x2 = cx + x; _y2 = cy - y;
        gfx_line(_x1, _y1, _x2, _y2, color);
        x = x + 1;
        px = px + twory2;
        if (p < 0) { p = p + ry2 + px; }
        else { y = y - 1; py = py - tworx2; p = p + ry2 + px - py; }
    }

    // Region 2 — p computed stepwise to avoid compiler MUL bugs
    {
        int t1, t2, t3;
        t1 = x * x + x;
        t2 = y - 1;
        t3 = t2 * t2;
        p = ry2 * t1;
        p = p + rx2 * t3;
        p = p - rx2 * ry2;
    }
    while (y >= 0) {
        int _x1, _y1, _x2, _y2;
        _x1 = cx - x; _y1 = cy + y; _x2 = cx + x; _y2 = cy + y;
        gfx_line(_x1, _y1, _x2, _y2, color);
        _x1 = cx - x; _y1 = cy - y; _x2 = cx + x; _y2 = cy - y;
        gfx_line(_x1, _y1, _x2, _y2, color);
        y = y - 1;
        py = py - tworx2;
        if (p > 0) { p = p + rx2 - py; }
        else { x = x + 1; px = px + twory2; p = p + rx2 - py + px; }
    }
}

// === Sector (filled arc/pie slice) ===
void gfx_sector(int cx, int cy, int r, int start_angle, int end_angle, int color) {
    int a;
    if (start_angle > end_angle) { int tmp = start_angle; start_angle = end_angle; end_angle = tmp; }
    for (a = start_angle; a <= end_angle; a++) {
        int rad = a;
        int x = cx + (r * (90 - rad) / 90);
        int y = cy + (r * rad / 90);
        gfx_line(cx, cy, x, y, color);
    }
}

// === Filled Sector (pie slice with radial lines) ===
void gfx_sector_fill(int cx, int cy, int r, int start_angle, int end_angle, int color) {
    int a;
    if (start_angle > end_angle) { int tmp = start_angle; start_angle = end_angle; end_angle = tmp; }
    // Draw radial lines from center to arc points (2-degree steps for fill density)
    for (a = start_angle; a <= end_angle; a = a + 2) {
        int angle = a % 360;
        int sx, sy;
        if (angle <= 90) {
            sx = (90 - angle) * r / 90;
            sy = angle * r / 90;
        } else if (angle <= 180) {
            sx = -(angle - 90) * r / 90;
            sy = (180 - angle) * r / 90;
        } else if (angle <= 270) {
            sx = -(270 - angle) * r / 90;
            sy = -(angle - 180) * r / 90;
        } else {
            sx = (angle - 270) * r / 90;
            sy = -(360 - angle) * r / 90;
        }
        gfx_line(cx, cy, cx + sx, cy + sy, color);
    }
    // Draw the arc outline for clean edges
    gfx_arc(cx, cy, r, start_angle, end_angle, color);
}

