// === Draw text using 8x16 bitmap font ===
void gfx_print(int x, int y, const char* text, int color) {
    gfx_print_scale(x, y, text, color, 1);
}

void gfx_print_scale(int x, int y, const char* text, int color, int scale) {
    int start_x = x;
    int cur_x = x;
    int cur_y = y;
    int i = 0;
    while (text[i] != '\0') {
        char ch = text[i];
        if (ch == '\n') {
            cur_x = start_x;
            cur_y = cur_y + 16 * scale;
            i++;
            continue;
        }
        if (ch < 32 || ch > 126) ch = 32;
        int char_offset = (ch - 32) * 16;
        int row, col;
        for (row = 0; row < 16; row++) {
            unsigned char bits = font8x16[char_offset + row];
            for (col = 0; col < 8; col++) {
                if (bits & (0x80 >> col)) {
                    int sx, sy;
                    for (sx = 0; sx < scale; sx++) {
                        for (sy = 0; sy < scale; sy++) {
                            _putpixel(cur_x + col * scale + sx,
                                       cur_y + row * scale + sy, color);
                        }
                    }
                }
            }
        }
        cur_x = cur_x + 8 * scale;
        i++;
    }
}

// === Flood fill (iterative with global stack) ===
#define FILL_STACK_MAX 256

// Global stack for flood fill (VML C compiler doesn't support large local/static arrays)
static int _flood_sx[FILL_STACK_MAX];
static int _flood_sy[FILL_STACK_MAX];

void gfx_flood_fill(int x, int y, int fill_color, int border_color) {
    int sp = 0;
    int w = gfx_w();
    int h = gfx_h();
    int target = _getpixel(x, y);

    if (target == fill_color || target == border_color) return;

    _flood_sx[sp] = x;
    _flood_sy[sp] = y;
    sp++;

    while (sp > 0 && sp < FILL_STACK_MAX) {
        sp--;
        int px = _flood_sx[sp];
        int py = _flood_sy[sp];

        if (px < 0 || px >= w || py < 0 || py >= h) continue;
        if (_getpixel(px, py) != target) continue;

        _putpixel(px, py, fill_color);

        if (sp + 4 < FILL_STACK_MAX) {
            _flood_sx[sp] = px + 1; _flood_sy[sp] = py; sp++;
            _flood_sx[sp] = px - 1; _flood_sy[sp] = py; sp++;
            _flood_sx[sp] = px; _flood_sy[sp] = py + 1; sp++;
            _flood_sx[sp] = px; _flood_sy[sp] = py - 1; sp++;
        }
    }
}

// === VML Entry Points (called by all language wrappers) ===
// Parameters are already in R0-R4 via calling convention

int gfx_screenshot(void) {
    asm("SYSCALL 200");
    asm("STORE R0, _vml_result_int");
    return _vml_result_int;
}

int gfx_put_image(int x, int y, int w, int h, const void* data) {
    asm("SYSCALL 201");
    asm("STORE R0, _vml_result_int");
    return _vml_result_int;
}

int gfx_get_image(int x, int y, int w, int h, void* buffer) {
    asm("SYSCALL 202");
    asm("STORE R0, _vml_result_int");
    return _vml_result_int;
}

int gfx_viewport(int x1, int y1, int x2, int y2) {
    asm("SYSCALL 203");
    asm("STORE R0, _vml_result_int");
    return _vml_result_int;
}
